import { IChatParentEvents } from './chat';
import { IGameChildEvents, ISubGameProxyEvents } from './game';
type Parameters<T> = T extends (...args: infer P) => unknown ? P : never;
export type MessageChannelType = 'web' | 'native';
export type NativePlatformType = 'ios' | 'android';
export type MessageSource = 'operator' | 'game' | 'chat';
export type GetPayload<O, K extends keyof O> = Parameters<O[K]>[0];
export type GetMessageEvent<O, K extends keyof O> = MessageEvent<{
    type: K;
    payload: GetPayload<O, K>;
    source: MessageSource;
}>;
export type GetUnionizedMessageEvent<O, K extends keyof O> = {
    [Key in keyof O]: GetMessageEvent<O, Key>;
}[K];
export type UnionizeArray<T extends readonly unknown[]> = T[number];
export interface IBaseParentEvents {
    onLoaded(): void;
}
export interface IMessageChannelBaseOptions {
    source: MessageSource;
}
export interface IWebMessageChannelOptions extends IMessageChannelBaseOptions {
    type: 'web';
    target: Window | HTMLIFrameElement;
    onMessageCallback?: (event: MessageEvent) => void;
}
export interface INativeMessageChannelOptions extends IMessageChannelBaseOptions {
    type: 'native';
    platform: NativePlatformType;
    handlers: IGameChildEvents;
    chatHandlers?: IChatParentEvents;
}
export type IMessageChannelOptions = IWebMessageChannelOptions | INativeMessageChannelOptions;
export interface IGameConnectionBaseOptions {
    operatorHandlers: IGameChildEvents;
    chatHandlers: Omit<IChatParentEvents, keyof IBaseParentEvents>;
    subGameProxyHandlers: ISubGameProxyEvents;
}
export interface IWebGameConnectionOptions extends IGameConnectionBaseOptions {
    type: 'web';
}
export interface INativeGameConnectionOptions extends IGameConnectionBaseOptions {
    type: 'native';
    platform: NativePlatformType;
}
export type IGameConnectionOptions = IWebGameConnectionOptions | INativeGameConnectionOptions;
export {};
